html:
{{ letter_head }}

{% set project_ref = doc.project %}
{% if doc.project %}
  {% set project_ref = frappe.db.get_value('Project', doc.project, 'project_name') or doc.project %}
{% endif %}

<style>
.cgm-inv {
  font-family: Arial, Helvetica, sans-serif;
  color: #171717;
  font-size: 11px;
  line-height: 1.45;
  background: #fff;
}
.cgm-inv * { box-sizing: border-box; }
.cgm-header {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 14px;
}
.cgm-header td { vertical-align: middle; padding: 0; }
.cgm-header .title {
  margin: 0;
  font-size: 24px;
  font-weight: 800;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #171717;
  line-height: 1.1;
}
.cgm-meta-table {
  border-collapse: collapse;
  margin-left: auto;
}
.cgm-meta-table td {
  padding: 2px 0;
  font-size: 10.5px;
  line-height: 1.55;
  white-space: nowrap;
}
.cgm-meta-table .lbl {
  color: #8b1a1a;
  font-weight: 700;
  padding-right: 14px;
  text-align: left;
}
.cgm-meta-table .val {
  color: #171717;
  font-weight: 700;
  text-align: right;
}
.cgm-rule {
  border: none;
  border-top: 1px solid #e5e5e5;
  margin: 0 0 14px;
}
.cgm-parties {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 14px;
}
.cgm-parties > tbody > tr > td {
  width: 50%;
  vertical-align: top;
  padding: 0 18px 0 0;
}
.cgm-parties > tbody > tr > td:last-child { padding: 0 0 0 18px; }
.cgm-section-label {
  margin: 0 0 7px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: #8b1a1a;
}
.cgm-party-name {
  margin: 0 0 4px;
  font-size: 12px;
  font-weight: 700;
  color: #171717;
}
.cgm-party-line {
  margin: 0;
  font-size: 10.5px;
  color: #444;
  line-height: 1.55;
}
.cgm-items {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 22px;
  table-layout: fixed;
}
.cgm-items thead tr th {
  background: #8b1a1a;
  color: #fff;
  padding: 8px 10px;
  text-align: left;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.4px;
}
.cgm-items thead tr th.num { text-align: right; }
.cgm-items tbody tr td {
  padding: 8px 10px;
  font-size: 10.5px;
  vertical-align: top;
  border-bottom: 1px solid #ececec;
  color: #171717;
}
.cgm-items tbody tr td.num {
  text-align: right;
  white-space: nowrap;
}
.cgm-items tbody tr:nth-child(even) td { background: #fafafa; }
.cgm-items tbody tr:last-child td { border-bottom: 1px solid #ddd; }
.cgm-bottom {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 8px;
  table-layout: fixed;
}
.cgm-bottom > tbody > tr > td { vertical-align: top; padding: 0; }
.cgm-bottom .col-left { width: 52%; padding-right: 36px; }
.cgm-bottom .col-right { width: 48%; padding-left: 8px; }
.cgm-terms {
  margin: 0;
  padding: 0;
  font-size: 10.5px;
  line-height: 1.65;
  color: #444;
}
.cgm-terms .terms-title {
  display: block;
  margin: 0 0 6px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #8b1a1a;
}
.cgm-totals {
  width: 100%;
  border-collapse: collapse;
}
.cgm-totals td {
  padding: 10px 0;
  font-size: 11.5px;
}
.cgm-totals .t-label {
  color: #8b1a1a;
  font-weight: 700;
  text-align: left;
}
.cgm-totals .t-value {
  color: #171717;
  font-weight: 700;
  text-align: right;
  white-space: nowrap;
}
.cgm-totals .total-row td {
  padding-top: 14px;
  border-top: 1.5px solid #171717;
  font-size: 14px;
  font-weight: 800;
  color: #171717;
}
.cgm-totals .total-row .t-label {
  color: #8b1a1a;
  font-weight: 800;
  letter-spacing: 0.8px;
  text-transform: uppercase;
}
.cgm-totals .total-row .t-value {
  font-size: 15px;
  font-weight: 800;
  color: #171717;
}
.cgm-in-words {
  margin: 12px 0 0;
  font-size: 10px;
  color: #555;
  line-height: 1.5;
}
</style>

<div class="cgm-inv">
  <table class="cgm-header">
    <tr>
      <td style="width:48%;">
        <h1 class="title">Purchase Invoice</h1>
      </td>
      <td style="width:52%;">
        <table class="cgm-meta-table">
          <tr>
            <td class="lbl">Posting Date</td>
            <td class="val">{{ frappe.utils.format_date(doc.posting_date, "dd-MM-yyyy") }}</td>
          </tr>
          <tr>
            <td class="lbl">Invoice No</td>
            <td class="val">{{ doc.name }}</td>
          </tr>
          {% if doc.bill_no %}
          <tr>
            <td class="lbl">Supplier Invoice No</td>
            <td class="val">{{ doc.bill_no }}</td>
          </tr>
          {% endif %}
        </table>
      </td>
    </tr>
  </table>

  <hr class="cgm-rule">

  <table class="cgm-parties">
    <tr>
      <td>
        <div class="cgm-section-label">Supplier</div>
        <div class="cgm-party-name">{{ doc.supplier_name or doc.supplier }}</div>
        {% if doc.address_display %}<div class="cgm-party-line">{{ doc.address_display }}</div>{% endif %}
      </td>
      <td>
        {% if doc.project %}
        <div class="cgm-section-label">Project</div>
        <div class="cgm-party-name">{{ project_ref }}</div>
        {% endif %}
        {% if doc.bill_date %}
        <div class="cgm-party-line" style="margin-top:10px;"><strong>Supplier Bill Date:</strong> {{ frappe.utils.format_date(doc.bill_date, "dd-MM-yyyy") }}</div>
        {% endif %}
      </td>
    </tr>
  </table>

  <table class="cgm-items">
    <thead>
      <tr>
        <th style="width:5%;">Sr</th>
        <th style="width:47%;">Item Description</th>
        <th class="num" style="width:12%;">Qty</th>
        <th class="num" style="width:18%;">Rate</th>
        <th class="num" style="width:18%;">Amount</th>
      </tr>
    </thead>
    <tbody>
      {% for item in doc.items %}
      <tr>
        <td>{{ loop.index }}</td>
        <td>{{ item.description or item.item_name }}</td>
        <td class="num">{{ item.get_formatted("qty", doc) }}</td>
        <td class="num">{{ item.get_formatted("rate", doc) }}</td>
        <td class="num">{{ item.get_formatted("amount", doc) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <table class="cgm-bottom">
    <tr>
      <td class="col-left">
        {% if doc.terms %}
        <div class="cgm-terms">
          <span class="terms-title">Terms</span>
          {{ doc.terms }}
        </div>
        {% endif %}
      </td>
      <td class="col-right">
        <table class="cgm-totals">
          {% if doc.total_qty %}
          <tr>
            <td class="t-label">Total Quantity</td>
            <td class="t-value">{{ doc.total_qty }}</td>
          </tr>
          {% endif %}
          <tr>
            <td class="t-label">Net Total</td>
            <td class="t-value">{{ doc.get_formatted("net_total") }}</td>
          </tr>
          {% for tax in doc.taxes or [] %}
            {% if tax.tax_amount %}
            <tr>
              <td class="t-label">{{ tax.description or tax.account_head }}</td>
              <td class="t-value">{{ tax.get_formatted("tax_amount") }}</td>
            </tr>
            {% endif %}
          {% endfor %}
          <tr class="total-row">
            <td class="t-label">Grand Total</td>
            <td class="t-value">{{ doc.get_formatted("grand_total") }}</td>
          </tr>
        </table>
        {% set amount_words = doc.in_words or frappe.utils.money_in_words(doc.grand_total, doc.currency) %}
        {% if amount_words %}
        <p class="cgm-in-words"><strong>In Words:</strong> {{ amount_words }}</p>
        {% endif %}
      </td>
    </tr>
  </table>
</div>

{%- if footer -%}
<div style="margin-top:24px;">{{ footer }}</div>
{%- endif -%}
